/* ---- robust dark-mode via filter invert (bundle patch) ---- */
(function(){
  // This is the most robust "no-rebuild" approach: invert the rendered output of the component,
  // then hue-rotate back so blues stay blue.
  const css = `
google-workflow-graph {
  /* make light canvas dark while preserving relative contrast */
  filter: invert(1) hue-rotate(180deg) brightness(0.92) contrast(1.08);
  background: #1a1a1a !important;
}

/* Prevent double-inverting anything you may mount INSIDE the graph that is already dark-themed. */
google-workflow-graph [data-no-invert="true"]{
  filter: invert(1) hue-rotate(180deg) !important;
}
`;
  try{
    const style = document.createElement("style");
    style.setAttribute("data-wg-filter-dark","true");
    style.textContent = css;
    (document.head || document.documentElement).appendChild(style);
  }catch(e){}
})();


/* ---- filter-dark patch with MUI background sampling + load verification ---- */
(function(){
  // Toggle to true for an obvious on-screen indicator that THIS file is active.
  const DEBUG = false;

  const FALLBACK_BG = "#202124"; // MUI-ish dark gray
  const HUE = 180;

  function parseRgb(s){
    const m = s && s.match(/rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)(?:\s*,\s*([\d.]+))?\s*\)/i);
    if(!m) return null;
    return {r:+m[1], g:+m[2], b:+m[3], a:(m[4]===undefined?1:+m[4])};
  }
  function luminance01(rgb){
    if(!rgb) return null;
    const srgb = [rgb.r, rgb.g, rgb.b].map(v=>{
      v/=255;
      return v<=0.04045 ? v/12.92 : Math.pow((v+0.055)/1.055, 2.4);
    });
    return 0.2126*srgb[0] + 0.7152*srgb[1] + 0.0722*srgb[2];
  }
  function rgbToHex(rgb){
    const h = (n)=>n.toString(16).padStart(2,"0");
    return "#" + h(rgb.r|0) + h(rgb.g|0) + h(rgb.b|0);
  }

  function pickMuiSurface(){
    // Try a few likely MUI surfaces; fall back to body bg.
    const candidates = [
      document.querySelector(".MuiAppBar-root"),
      document.querySelector(".MuiDrawer-paper"),
      document.querySelector(".MuiPaper-root"),
      document.querySelector(".MuiToolbar-root"),
      document.querySelector(".MuiContainer-root"),
      document.querySelector("main"),
      document.querySelector("header"),
      document.body
    ].filter(Boolean);

    for(const el of candidates){
      const bg = parseRgb(getComputedStyle(el).backgroundColor);
      const lum = luminance01(bg);
      if(bg && lum !== null && lum < 0.35 && bg.a > 0.2) return {bg, lum};
    }
    return {bg: null, lum: null};
  }

  function computeFilter(lum){
    // If MUI surface is darker (lum ~ 0.02-0.08), we need a lighter brightness to avoid "crushed" blacks.
    // If it’s already mid-dark (lum ~ 0.10-0.18), lower brightness.
    // Clamp to keep it sane.
    const b = lum === null ? 1.16 : Math.min(1.40, Math.max(1.02, 1.34 - 1.35*lum));
    const c = lum === null ? 1.00 : Math.min(1.08, Math.max(0.92, 1.02 - 0.35*lum));
    const s = 0.92;
    return {brightness: +b.toFixed(3), contrast: +c.toFixed(3), saturate: s};
  }

  function install(){
    const {bg, lum} = pickMuiSurface();
    const bgHex = bg ? rgbToHex(bg) : FALLBACK_BG;
    const {brightness, contrast, saturate} = computeFilter(lum);

    // Allow manual override for quick tuning in devtools:
    // window.__WG_FILTER = { brightness: 1.08, contrast: 1.02, saturate: 0.98, background: "#202124" }
    const o = (typeof window !== "undefined" && window.__WG_FILTER) ? window.__WG_FILTER : null;
    const B = o?.brightness ?? brightness;
    const C = o?.contrast ?? contrast;
    const S = o?.saturate ?? saturate;
    const BG = o?.background ?? bgHex;

    const css = `
google-workflow-graph{
  filter: invert(1) hue-rotate(${HUE}deg) brightness(${B}) contrast(${C}) saturate(${S}) !important;
  background: ${BG} !important;
  ${DEBUG ? "outline: 4px solid magenta !important;" : ""}
}
`;
    const style = document.createElement("style");
    style.setAttribute("data-wg-filter-dark-sampled","true");
    style.textContent = css;
    (document.head || document.documentElement).appendChild(style);

    console.info("[workflow-graph] filter-dark-sampled active", {BG, B, C, S});
  }

  try{
    // Run after first paint so computed styles exist.
    if(document.readyState === "loading"){
      document.addEventListener("DOMContentLoaded", install, {once:true});
    } else {
      install();
    }
  }catch(e){
    // If anything fails, still apply a reasonable default.
    try{
      const style = document.createElement("style");
      style.setAttribute("data-wg-filter-dark-sampled","true");
      style.textContent = `google-workflow-graph{filter:invert(1) hue-rotate(180deg) brightness(1.0) contrast(1.05) saturate(.98) !important;background:${FALLBACK_BG} !important;}`;
      (document.head || document.documentElement).appendChild(style);
      console.info("[workflow-graph] filter-dark-sampled fallback active");
    }catch(_){}
  }
})();


/* ---- additive RGB lift (offset) via SVG feColorMatrix ---- */
(function(){
  const DEFAULT_LIFT = 0.10; // add 10% to each RGB channel (clamped by renderer)

  function clamp01(x){ return Math.max(0, Math.min(1, x)); }

  function getLift(){
    try{
      const s = localStorage.getItem("WG_FILTER_LIFT");
      if(s == null) return DEFAULT_LIFT;
      const v = parseFloat(s);
      if(!Number.isFinite(v)) return DEFAULT_LIFT;
      return clamp01(v);
    }catch(_){
      return DEFAULT_LIFT;
    }
  }

  function ensureSvgFilter(lift){
    const id = "wg-lift";
    let svg = document.getElementById("wg-lift-svg");
    if(!svg){
      svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
      svg.setAttribute("id", "wg-lift-svg");
      svg.setAttribute("aria-hidden", "true");
      svg.setAttribute("width", "0");
      svg.setAttribute("height", "0");
      svg.style.position = "absolute";
      svg.style.left = "-9999px";
      (document.body || document.documentElement).appendChild(svg);
    }

    // Update filter contents (rewrite to avoid DOM diff hassles)
    svg.innerHTML = `
      <filter id="${id}" color-interpolation-filters="sRGB">
        <feColorMatrix type="matrix" values="
          1 0 0 0 ${lift}
          0 1 0 0 ${lift}
          0 0 1 0 ${lift}
          0 0 0 1 0
        "/>
      </filter>
    `;
  }

  function install(){
    const lift = getLift();
    ensureSvgFilter(lift);

    // Inject CSS that splices url(#wg-lift) into the filter chain.
    // Keep it separate so it reliably wins in cascade.
    const style = document.createElement("style");
    style.setAttribute("data-wg-filter-lift","true");
    style.textContent = `
google-workflow-graph{
  /* Insert additive lift after invert/hue rotate to brighten without changing black point too much */
  filter: invert(1) hue-rotate(180deg) url(#wg-lift) !important;
}
`;
    (document.head || document.documentElement).appendChild(style);

    console.info("[workflow-graph] lift active", {lift});
  }

  try{
    if(document.readyState === "loading"){
      document.addEventListener("DOMContentLoaded", install, {once:true});
    } else {
      install();
    }
  }catch(_){}
})();
